// Hand-written. Not generated by Speakeasy.
//
// Every combination that decides whether a resource is dropped, in one table.
//
// This file exists because the same bug was found three times in three
// reviews, each time in a combination nobody had enumerated: the body said
// gone but was an HTML page, the record agreed because a refresh had just
// rewritten it, the state had no record at all. Each fix was tested against
// the case that prompted it and shipped as done.
//
// So the cases are enumerated here rather than chosen. If a combination is
// not in this table, that is visible, which is the point.
package provider

import (
	"context"
	"fmt"
	"net/http"
	"strings"
	"testing"

	"github.com/authlete/terraform-provider-authlete/v3/internal/sdk/models/operations"
)

type fakeServiceReader struct {
	status int
	body   string
	fail   bool
}

func (f fakeServiceReader) get() *http.Response {
	r := &http.Response{StatusCode: f.status, Header: http.Header{}}
	r.Body = &matrixBody{strings.NewReader(f.body)}
	req, _ := http.NewRequest(http.MethodGet, "https://api.example/api/1/service/get", nil)
	r.Request = req.WithContext(context.WithValue(req.Context(), noteKey{}, &note{body: []byte(f.body)}))
	return r
}

type matrixBody struct{ *strings.Reader }

func (m *matrixBody) Close() error { return nil }

func matrixResponse(where Location, status int, body string) *http.Response {
	r := &http.Response{StatusCode: status, Header: http.Header{}}
	r.Body = &matrixBody{strings.NewReader(body)}
	host := where.Host
	if host == "" {
		host = "api.example"
	}
	req, _ := http.NewRequest(http.MethodGet, "https://"+host+"/api/1/service/get", nil)
	r.Request = req.WithContext(context.WithValue(req.Context(),
		noteKey{}, &note{where: where, body: []byte(body)}))
	return r
}

// The bodies that do and do not mean "not there".
const (
	bodyServerGone = `{"resultCode":"A458203","resultMessage":"Service not found"}`
	bodyIdpGone    = `{"error":"Service is not found"}`
	bodyClientGone = `{"resultCode":"A001214","resultMessage":"no such client"}`
	bodyNginx      = `<html><body>nginx: Service is not found</body></html>`
	bodyQuoted     = `{"resultCode":"A999999","resultMessage":"see A458203 for details"}`
	bodyLongerCode = `{"resultCode":"A4582031","resultMessage":"unrelated"}`
	bodyEmpty      = ``
)

var (
	locHere  = Location{Host: "api.example", IdpHost: "idp.example", Org: 11, API: 53285}
	locHost  = Location{Host: "other.example", IdpHost: "idp.example", Org: 11, API: 53285}
	locOrg   = Location{Host: "api.example", IdpHost: "idp.example", Org: 99, API: 53285}
	locIdp   = Location{Host: "api.example", IdpHost: "other.example", Org: 11, API: 53285}
	locAPI   = Location{Host: "api.example", IdpHost: "idp.example", Org: 11, API: 99999}
	locLegit = Location{Host: "api.example"}
)

// A record written before the IdP coordinates were stored holds a bare host
// string. It must still work, and must still catch a changed cluster.
func TestMatrixLegacyRecord(t *testing.T) {
	ctx := context.Background()
	for _, tc := range []struct {
		name      string
		now       Location
		wantMoved bool
	}{
		{"same cluster", locHere, false},
		{"other cluster", locHost, true},
		{"same cluster, different organization", locOrg, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			p := &fakePrivate{data: map[string][]byte{hostKey: []byte(`"api.example"`)}}
			if moved := movedHost(ctx, p, matrixResponse(tc.now, 403, bodyServerGone)) != ""; moved != tc.wantMoved {
				t.Errorf("movedHost reports a move = %v, want %v", moved, tc.wantMoved)
			}
			if !hasRecord(ctx, p) {
				t.Error("a legacy record must count as a record")
			}
		})
	}
}

func recordOf(t *testing.T, where *Location) *fakePrivate {
	t.Helper()
	p := &fakePrivate{}
	if where != nil {
		rememberHost(context.Background(), p, matrixResponse(*where, 200, "{}"))
	}
	return p
}

// Does the body alone say "not there"? Nothing may be dropped on a body that
// does not, whatever the status.
func TestMatrixBodyMeansGone(t *testing.T) {
	for _, tc := range []struct {
		name    string
		status  int
		body    string
		service bool // the service itself is missing
		client  bool // this client is missing
		either  bool // what a client resource acts on: its clients went with it
	}{
		{"server 403 A458203", 403, bodyServerGone, true, false, true},
		{"idp 404 not found", 404, bodyIdpGone, true, false, true},
		{"client 404 A001214", 404, bodyClientGone, false, true, true},
		{"client 404 A001212", 404, `{"resultCode":"A001212","resultMessage":"x"}`, false, true, true},
		{"nginx page quoting the phrase", 404, bodyNginx, false, false, false},
		{"another error quoting the code", 403, bodyQuoted, false, false, false},
		{"a longer code", 403, bodyLongerCode, false, false, false},
		{"empty body", 404, bodyEmpty, false, false, false},
		{"empty body, 403", 403, bodyEmpty, false, false, false},
		{"permission failure", 403, `{"resultCode":"A000000","resultMessage":"forbidden"}`, false, false, false},
		{"the gone code but a 200", 200, bodyServerGone, false, false, false},
		{"the gone code but a 500", 500, bodyServerGone, false, false, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			for name, got := range map[string]struct{ have, want bool }{
				"serviceIsGone":         {serviceIsGone(matrixResponse(locHere, tc.status, tc.body)), tc.service},
				"clientIsGone":          {clientIsGone(matrixResponse(locHere, tc.status, tc.body)), tc.client},
				"clientOrServiceIsGone": {clientOrServiceIsGone(matrixResponse(locHere, tc.status, tc.body)), tc.either},
			} {
				if got.have != got.want {
					t.Errorf("%s = %v, want %v", name, got.have, got.want)
				}
			}
		})
	}
}

// Given a body that does mean "not there", what does the record say? Every
// state a record can be in, against every coordinate that can be wrong.
func TestMatrixRecordDecides(t *testing.T) {
	for _, tc := range []struct {
		name      string
		record    *Location
		now       Location
		wantMoved bool
		wantNoRec bool
	}{
		{"no record at all", nil, locHere, false, true},
		{"record matches", &locHere, locHere, false, false},
		{"wrong cluster", &locHere, locHost, true, false},
		{"wrong organization", &locHere, locOrg, true, false},
		{"wrong identity server", &locHere, locIdp, true, false},
		{"wrong api server", &locHere, locAPI, true, false},
		// A record written by this version with no organization is not the
		// same as no organization being configured now. Refusing is the safe
		// direction, and the message says what to put back.
		{"record predates organization_id being set", &locLegit, locHere, true, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			ctx := context.Background()
			p := recordOf(t, tc.record)
			res := matrixResponse(tc.now, 403, bodyServerGone)

			if moved := movedHost(ctx, p, res) != ""; moved != tc.wantMoved {
				t.Errorf("movedHost reports a move = %v, want %v", moved, tc.wantMoved)
			}
			if noRec := !hasRecord(ctx, p); noRec != tc.wantNoRec {
				t.Errorf("no record = %v, want %v", noRec, tc.wantNoRec)
			}
		})
	}
}

// A refresh rewrites the record from the configuration, so for a service the
// record cannot be the last word. The cluster is asked, and only a cluster
// that also says gone permits the delete.
func TestMatrixServiceDeleteAsksTheCluster(t *testing.T) {
	for _, tc := range []struct {
		name      string
		cluster   fakeServiceReader
		wantGone  bool
		wantKnown bool
	}{
		{"cluster still has it", fakeServiceReader{status: 200}, false, true},
		{"cluster agrees it is gone", fakeServiceReader{status: 403, body: bodyServerGone}, false, true},
		{"cluster returns an nginx page", fakeServiceReader{status: 404, body: bodyNginx}, false, false},
		{"cluster returns an empty 500", fakeServiceReader{status: 500, body: bodyEmpty}, false, false},
		{"cluster unreachable", fakeServiceReader{fail: true}, false, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			exists, known := serviceStillExists(context.Background(), stubReader{tc.cluster}, 1)
			wantExists := tc.cluster.status == http.StatusOK && !tc.cluster.fail
			if exists != wantExists || known != tc.wantKnown {
				t.Errorf("exists=%v known=%v, want exists=%v known=%v",
					exists, known, wantExists, tc.wantKnown)
			}
			// The delete proceeds only when the cluster positively says gone.
			mayDelete := known && !exists
			t.Logf("may delete: %v", mayDelete)
			if tc.name == "cluster agrees it is gone" && !mayDelete {
				t.Error("a genuine deletion must still be deletable")
			}
			if tc.name != "cluster agrees it is gone" && mayDelete {
				t.Error("the delete must not proceed unless the cluster says gone")
			}
		})
	}
}

// A nil reader must never read as "gone".
func TestMatrixNoReaderIsNotGone(t *testing.T) {
	if exists, known := serviceStillExists(context.Background(), nil, 1); exists || known {
		t.Errorf("exists=%v known=%v, want both false", exists, known)
	}
}

// stubReader answers one canned response, or fails.
type stubReader struct{ f fakeServiceReader }

func (s stubReader) ServiceGetAPI(ctx context.Context, req operations.ServiceGetAPIRequest, opts ...operations.Option) (*operations.ServiceGetAPIResponse, error) {
	if s.f.fail {
		return nil, errStub
	}
	return &operations.ServiceGetAPIResponse{RawResponse: s.f.get()}, nil
}

var errStub = fmt.Errorf("transport failure")

// Every call site now routes through one decision, so the table covers all
// four at once: service and client, Read and Delete.
//
// The case that prompted it: service Delete had no check that anything had
// ever been recorded, and its cluster confirmation asks the host from the
// same configuration. With no record and a wrong server_url, the wrong
// cluster answers A458203, the confirmation agrees, and destroy reported
// success while the service kept running.
func TestMatrixMayTreatAsGone(t *testing.T) {
	ctx := context.Background()
	clusterSaysGone := func() (bool, bool) { return false, true }
	clusterSaysThere := func() (bool, bool) { return true, true }
	clusterCannotTell := func() (bool, bool) { return false, false }

	for _, tc := range []struct {
		name    string
		record  *Location
		now     Location
		confirm func() (bool, bool)
		want    bool
		expect  string // a phrase the refusal must carry
	}{
		// Read paths, no second place to ask.
		{"read, record matches", &locHere, locHere, nil, true, ""},
		{"read, no record", nil, locHere, nil, false, "state rm"},
		{"read, wrong cluster", &locHere, locHost, nil, false, "last seen"},
		{"read, wrong organization", &locHere, locOrg, nil, false, "last seen"},

		// Client delete behaves exactly as client read.
		{"client delete, no record", nil, locHere, nil, false, "state rm"},

		// Service delete, where the identity server answered.
		{"service delete, record matches, cluster agrees", &locHere, locHere, clusterSaysGone, true, ""},
		{"service delete, record matches, cluster still has it", &locHere, locHere, clusterSaysThere, false, "still exists"},
		{"service delete, record matches, cluster cannot tell", &locHere, locHere, clusterCannotTell, false, "still exists"},
		{"service delete, wrong organization", &locHere, locOrg, clusterSaysGone, false, "last seen"},

		// The gap: no record, wrong cluster. The confirmation asks that same
		// wrong cluster, so it is not independent evidence.
		{"service delete, no record, wrong cluster", nil, locHost, clusterSaysGone, false, "state rm"},
		{"service delete, no record, right cluster", nil, locHere, clusterSaysGone, false, "state rm"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			p := recordOf(t, tc.record)
			res := matrixResponse(tc.now, 403, bodyServerGone)
			gone, summary, detail := mayTreatAsGone(ctx, p, res, "service", "42", tc.confirm)
			if gone != tc.want {
				t.Fatalf("mayTreatAsGone = %v, want %v (%s)", gone, tc.want, summary)
			}
			if tc.want {
				return
			}
			if !strings.Contains(summary+detail, tc.expect) {
				t.Errorf("the refusal does not mention %q:\n%s\n%s", tc.expect, summary, detail)
			}
		})
	}
}
